//! Prop accessor generation for pyclass nodes.
//!
//! # Why this shape
//!
//! PyO3 0.30 rejects `macro_rules!` invocations **inside** `#[pymethods]` blocks:
//! the proc macro parses the whole impl block before inner macros expand, and
//! errors instead of ignoring. So accessors are generated by a macro invoked at
//! **module level**, expanding to one or more additional `#[pymethods] impl
//! <Class>` blocks. PyO3 0.30 accumulates multiple `#[pymethods]` blocks onto
//! the same pyclass.
//!
//! ```ignore
//! #[pymethods]
//! impl PyTimer {
//!     #[new] fn new() -> ... { ... }
//! }
//!
//! pite_props! {
//!     PyTimer {
//!         wait_time: Num,
//!         current_elapsed: Num [read_only],
//!     }
//! }
//! ```
//!
//! Inside each expansion, `paste::paste!` runs **outside** `#[pymethods]`, so
//! the setter name `set_<key>` is already spelled when PyO3's proc macro runs.
//!
//! # Kinds
//!
//! - `Num`   → `f64`
//! - `Int`   → `i64`
//! - `Bool`  → `bool`
//! - `Str`   → `String`
//! - `Color` → `(u8, u8, u8, u8)` (rich `PyColor` proxy will replace this later;
//!   the read/write path is host-tied and stays compatible)
//! - `Vec2`  → `Py<Vec2>`. The pyclass MUST declare
//!   `pub(crate) <key>: Py<crate::vec2::Vec2>` and initialize it in `#[new]`.
//!
//! # Read-only
//!
//! Suffix an entry with `[read_only]` to skip the setter:
//! `current_elapsed: Num [read_only],` — `self.current_elapsed` reads from the
//! tree; assigning raises `AttributeError` (no setter emitted).

#[macro_export]
macro_rules! pite_props {
    // ======================================================================
    // Entry dispatch: peel one prop at a time, recurse on the tail.
    // `[` is a distinct token from `,` / `}`, so `[read_only]` is unambiguous
    // against "next entry starts with an ident".
    // ======================================================================

    // ---- Empty body ----
    ($cls:ident { }) => {};

    // ---- Read-only, no trailing comma ----
    ($cls:ident { $key:ident : $kind:ident [read_only] }) => {
        $crate::pite_props!(@one $cls; $key : $kind, read_only);
    };

    // ---- Read-only, trailing comma ----
    ($cls:ident { $key:ident : $kind:ident [read_only], }) => {
        $crate::pite_props!(@one $cls; $key : $kind, read_only);
    };

    // ---- Read-only + more entries ----
    ($cls:ident { $key:ident : $kind:ident [read_only], $($rest:tt)+ }) => {
        $crate::pite_props!(@one $cls; $key : $kind, read_only);
        $crate::pite_props!($cls { $($rest)+ });
    };

    // ---- Regular, no trailing comma ----
    ($cls:ident { $key:ident : $kind:ident }) => {
        $crate::pite_props!(@one $cls; $key : $kind);
    };

    // ---- Regular, trailing comma ----
    ($cls:ident { $key:ident : $kind:ident, }) => {
        $crate::pite_props!(@one $cls; $key : $kind);
    };

    // ---- Regular + more entries ----
    ($cls:ident { $key:ident : $kind:ident, $($rest:tt)+ }) => {
        $crate::pite_props!(@one $cls; $key : $kind);
        $crate::pite_props!($cls { $($rest)+ });
    };

    // ======================================================================
    // @one arms — emit exactly one `#[pymethods] impl` block per prop.
    // ======================================================================

    // ---- Num (f64) ----
    (@one $cls:ident; $key:ident : Num) => {
        $crate::paste::paste! {
            #[::pyo3::pymethods]
            impl $cls {
                #[getter]
                fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<f64> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    Ok(host.get_f64(&node, stringify!($key)))
                }
                #[setter]
                fn [<set_ $key>](
                    slf: &::pyo3::Bound<'_, Self>,
                    v: f64,
                ) -> ::pyo3::PyResult<()> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    host.set_prop(&node, stringify!($key), ::pite_core::PropValue::Num(v));
                    Ok(())
                }
            }
        }
    };
    (@one $cls:ident; $key:ident : Num, read_only) => {
        #[::pyo3::pymethods]
        impl $cls {
            #[getter]
            fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<f64> {
                let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                Ok(host.get_f64(&node, stringify!($key)))
            }
        }
    };

    // ---- Int (i64) ----
    (@one $cls:ident; $key:ident : Int) => {
        $crate::paste::paste! {
            #[::pyo3::pymethods]
            impl $cls {
                #[getter]
                fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<i64> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    Ok(host.get_i64(&node, stringify!($key)))
                }
                #[setter]
                fn [<set_ $key>](
                    slf: &::pyo3::Bound<'_, Self>,
                    v: i64,
                ) -> ::pyo3::PyResult<()> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    host.set_prop(&node, stringify!($key), ::pite_core::PropValue::Int(v));
                    Ok(())
                }
            }
        }
    };
    (@one $cls:ident; $key:ident : Int, read_only) => {
        #[::pyo3::pymethods]
        impl $cls {
            #[getter]
            fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<i64> {
                let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                Ok(host.get_i64(&node, stringify!($key)))
            }
        }
    };

    // ---- Bool ----
    (@one $cls:ident; $key:ident : Bool) => {
        $crate::paste::paste! {
            #[::pyo3::pymethods]
            impl $cls {
                #[getter]
                fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<bool> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    Ok(host.get_bool(&node, stringify!($key)))
                }
                #[setter]
                fn [<set_ $key>](
                    slf: &::pyo3::Bound<'_, Self>,
                    v: bool,
                ) -> ::pyo3::PyResult<()> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    host.set_prop(&node, stringify!($key), ::pite_core::PropValue::Bool(v));
                    Ok(())
                }
            }
        }
    };
    (@one $cls:ident; $key:ident : Bool, read_only) => {
        #[::pyo3::pymethods]
        impl $cls {
            #[getter]
            fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<bool> {
                let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                Ok(host.get_bool(&node, stringify!($key)))
            }
        }
    };

    // ---- Str (String) ----
    (@one $cls:ident; $key:ident : Str) => {
        $crate::paste::paste! {
            #[::pyo3::pymethods]
            impl $cls {
                #[getter]
                fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<String> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    Ok(host.get_string(&node, stringify!($key)))
                }
                #[setter]
                fn [<set_ $key>](
                    slf: &::pyo3::Bound<'_, Self>,
                    v: String,
                ) -> ::pyo3::PyResult<()> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    host.set_prop(&node, stringify!($key), ::pite_core::PropValue::Str(v));
                    Ok(())
                }
            }
        }
    };
    (@one $cls:ident; $key:ident : Str, read_only) => {
        #[::pyo3::pymethods]
        impl $cls {
            #[getter]
            fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<String> {
                let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                Ok(host.get_string(&node, stringify!($key)))
            }
        }
    };

    // ---- Color (4-tuple of u8) ----
    (@one $cls:ident; $key:ident : Color) => {
        $crate::paste::paste! {
            #[::pyo3::pymethods]
            impl $cls {
                #[getter]
                fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<(u8, u8, u8, u8)> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    Ok(host.get_color_tuple(&node, stringify!($key)))
                }
                #[setter]
                fn [<set_ $key>](
                    slf: &::pyo3::Bound<'_, Self>,
                    v: (u8, u8, u8, u8),
                ) -> ::pyo3::PyResult<()> {
                    let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                    host.set_prop(
                        &node,
                        stringify!($key),
                        ::pite_core::PropValue::Color(v.0, v.1, v.2, v.3),
                    );
                    Ok(())
                }
            }
        }
    };
    (@one $cls:ident; $key:ident : Color, read_only) => {
        #[::pyo3::pymethods]
        impl $cls {
            #[getter]
            fn $key(slf: &::pyo3::Bound<'_, Self>) -> ::pyo3::PyResult<(u8, u8, u8, u8)> {
                let (host, node) = $crate::python::host_and_path(slf.as_any())?;
                Ok(host.get_color_tuple(&node, stringify!($key)))
            }
        }
    };

    // ---- Vec2 (pyclass field `pub(crate) <key>: Py<Vec2>`) ----
    (@one $cls:ident; $key:ident : Vec2) => {
        $crate::paste::paste! {
            #[::pyo3::pymethods]
            impl $cls {
                #[getter]
                fn $key<'py>(
                    slf: &::pyo3::Bound<'py, Self>,
                    py: ::pyo3::Python<'py>,
                ) -> ::pyo3::Py<$crate::vec2::Vec2> {
                    let obj = slf.borrow().$key.clone_ref(py);
                    // Install the host target on first access so
                    // `self.velocity.x = 5` and `self.velocity = (5, 6)`
                    // both reach the tree — no eager per-field walk needed
                    // in `exec()`.
                    if obj.borrow(py).target.is_none() {
                        if let Ok((host, node)) =
                            $crate::python::host_and_path(slf.as_any())
                        {
                            obj.borrow_mut(py).set_target(
                                host,
                                node,
                                stringify!($key).to_string(),
                            );
                        }
                    }
                    obj
                }
                #[setter]
                fn [<set_ $key>]<'py>(
                    slf: &::pyo3::Bound<'py, Self>,
                    py: ::pyo3::Python<'py>,
                    val: &::pyo3::Bound<'_, ::pyo3::PyAny>,
                ) -> ::pyo3::PyResult<()> {
                    // Extract both components first — the source Vec2 may be
                    // the same object we're about to mutate (`self.position =
                    // self.position`), so we must not hold a mutable borrow
                    // while extracting.
                    let (x, y) = if let Ok(other) = val.extract::<$crate::vec2::Vec2>() {
                        (other.x(), other.y())
                    } else if let Ok(t) = val.extract::<(f64, f64)>() {
                        t
                    } else {
                        return Err(::pyo3::exceptions::PyTypeError::new_err(
                            concat!(stringify!($key), " must be Vec2 or (x, y) tuple"),
                        ));
                    };
                    let obj = slf.borrow().$key.clone_ref(py);
                    if obj.borrow(py).target.is_none() {
                        if let Ok((host, node)) =
                            $crate::python::host_and_path(slf.as_any())
                        {
                            obj.borrow_mut(py).set_target(
                                host,
                                node,
                                stringify!($key).to_string(),
                            );
                        }
                    }
                    obj.borrow_mut(py).set_xy(x, y);
                    Ok(())
                }
            }
        }
    };
    (@one $cls:ident; $key:ident : Vec2, read_only) => {
        #[::pyo3::pymethods]
        impl $cls {
            #[getter]
            fn $key<'py>(
                slf: &::pyo3::Bound<'py, Self>,
                py: ::pyo3::Python<'py>,
            ) -> ::pyo3::Py<$crate::vec2::Vec2> {
                let obj = slf.borrow().$key.clone_ref(py);
                if obj.borrow(py).target.is_none() {
                    if let Ok((host, node)) =
                        $crate::python::host_and_path(slf.as_any())
                    {
                        obj.borrow_mut(py).set_target(
                            host,
                            node,
                            stringify!($key).to_string(),
                        );
                    }
                }
                obj
            }
        }
    };
}

// ---------------------------------------------------------------------------
// Python ↔ PropValue conversions for the custom-prop API
// ---------------------------------------------------------------------------

/// Convert an arbitrary Python object into a `PropValue`, picking the first
/// variant whose Rust type extracts without error. Order matters:
///
/// - `bool` before `int` (bool is a subclass of int; `extract::<i64>()` on
///   `True` returns 1, so the bool check has to come first).
/// - `int` before `float` (an int extracts as `f64` too, but we want
///   `Int(1)` for `1`, not `Num(1.0)`).
/// - `String` before tuples (a string never extracts as a 2-tuple, but the
///   order is stable and cheap).
/// - `(f64, f64)` (vec2) before `(u8, u8, u8[, u8])` (color): the two are
///   disjoint by length, so the first fitting pattern wins.
pub(crate) fn py_to_prop(
    value: &::pyo3::Bound<'_, ::pyo3::PyAny>,
) -> ::pyo3::PyResult<pite_core::PropValue> {
    use ::pyo3::types::{PyAnyMethods, PyBool};

    if value.is_instance_of::<PyBool>() {
        return Ok(pite_core::PropValue::Bool(value.extract::<bool>()?));
    }
    if let Ok(i) = value.extract::<i64>() {
        return Ok(pite_core::PropValue::Int(i));
    }
    if let Ok(f) = value.extract::<f64>() {
        return Ok(pite_core::PropValue::Num(f));
    }
    if let Ok(s) = value.extract::<String>() {
        return Ok(pite_core::PropValue::Str(s));
    }
    if let Ok((x, y)) = value.extract::<(f64, f64)>() {
        return Ok(pite_core::PropValue::Vec2(x, y));
    }
    if let Ok((r, g, b)) = value.extract::<(u8, u8, u8)>() {
        return Ok(pite_core::PropValue::Color(r, g, b, 255));
    }
    if let Ok((r, g, b, a)) = value.extract::<(u8, u8, u8, u8)>() {
        return Ok(pite_core::PropValue::Color(r, g, b, a));
    }
    Err(::pyo3::exceptions::PyTypeError::new_err(
        "value must be str, int, float, bool, (x, y) tuple, or (r, g, b[, a]) tuple",
    ))
}

/// Convert a `PropValue` back to a plain Python value (`str`, `float`, `int`,
/// `bool`, `(x, y)`, or `(r, g, b, a)`).
pub(crate) fn prop_to_py(
    py: ::pyo3::Python<'_>,
    value: &pite_core::PropValue,
) -> ::pyo3::PyResult<::pyo3::Py<::pyo3::PyAny>> {
    use ::pyo3::IntoPyObjectExt;
    match value {
        pite_core::PropValue::Str(s) => s.clone().into_py_any(py),
        pite_core::PropValue::Num(f) => f.into_py_any(py),
        pite_core::PropValue::Int(i) => i.into_py_any(py),
        pite_core::PropValue::Bool(b) => b.into_py_any(py),
        pite_core::PropValue::Vec2(x, y) => (*x, *y).into_py_any(py),
        pite_core::PropValue::Color(r, g, b, a) => (*r, *g, *b, *a).into_py_any(py),
    }
}

#[cfg(test)]
mod tests {
    //! Compilation test: `pite_props!` must expand to valid `#[pymethods]`
    //! impl blocks with zero nested macros by the time PyO3's proc macro runs.
    //! If it doesn't, this module won't compile.

    use crate::python::PyNode;
    use crate::vec2::Vec2;
    use pyo3::prelude::*;
    use pyo3::PyClassInitializer;

    #[pyclass(extends = PyNode, name = "PyPropsTest")]
    pub(crate) struct PyPropsTest {
        pub(crate) position: Py<Vec2>,
    }

    #[pymethods]
    impl PyPropsTest {
        #[new]
        fn new(py: Python<'_>) -> PyResult<PyClassInitializer<Self>> {
            let pos = Py::new(py, Vec2::new(0.0, 0.0))?;
            Ok(PyClassInitializer::from(PyNode::new()).add_subclass(Self { position: pos }))
        }
    }

    crate::pite_props! {
        PyPropsTest {
            position: Vec2,
            count: Num,
            counted: Num [read_only],
            index: Int,
            alive: Bool,
            nickname: Str,
            tint: Color,
        }
    }
}
